from typing import List

from textkit.normalize_whitespace import normalize_whitespace

ABBREVIATIONS = frozenset(
    {
        "Mr.",
        "Mrs.",
        "Ms.",
        "Dr.",
        "Prof.",
        "St.",
        "vs.",
        "e.g.",
        "i.e.",
    }
)

_TERMINATORS = {".", "!", "?"}
_CLOSERS = {'"', "'", ")", "]"}
_OPENERS = {'"', "'", "(", "["}


def _strip_closers(word: str) -> str:
    i = len(word)
    while i > 0 and word[i - 1] in _CLOSERS:
        i -= 1
    return word[:i]


def _ends_with_terminator(word: str) -> bool:
    stripped = _strip_closers(word)
    if not stripped:
        return False
    return stripped[-1] in _TERMINATORS


def _starts_boundary(word: str) -> bool:
    if not word:
        return False
    first = word[0]
    if first in _OPENERS:
        return True
    if first.isdigit():
        return True
    return first.isupper()


def split_sentences(text: str) -> List[str]:
    """Split prose into sentences, respecting common abbreviations."""
    cleaned = normalize_whitespace(text)
    if not cleaned:
        return []

    words = cleaned.split(" ")
    sentences: List[str] = []
    current: List[str] = []

    for i, word in enumerate(words):
        current.append(word)
        if _ends_with_terminator(word) and word not in ABBREVIATIONS:
            if i + 1 < len(words) and _starts_boundary(words[i + 1]):
                sentences.append(" ".join(current))
                current = []

    if current:
        sentences.append(" ".join(current))
    return sentences
