from textkit.tokenize_words import tokenize_words


def top_words(text: str, k: int, stopwords: Optional[Iterable[str]] = None) -> List[Tuple[str, int]]:
    """Return the `k` most frequent words of `text` as (word, count) pairs.

    Words come from tokenize_words(). Words listed in `stopwords` (compared
    case-insensitively) are ignored, and so are tokens made only of digits.
    If fewer than k distinct words remain, all of them are returned.
    Raises ValueError if k < 0.
    """
    if k < 0:
        raise ValueError("k must be >= 0")
    if k == 0:
        return []

    stop = set(w.lower() for w in stopwords) if stopwords is not None else set()

    counts: dict = {}
    for word in tokenize_words(text):
        low = word.lower()
        if low in stop:
            continue
        if low.isdigit():
            continue
        counts[low] = counts.get(low, 0) + 1

    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ordered[:k]
